if (!root) return false;

Node* current = root;
while (!current->is_leaf) {
    int pos = std::upper_bound(current->keys.begin(), current->keys.end(), key) - current->keys.begin();
    if (pos > 0 && current->keys[pos-1] == key) {
        return true;
    }
    current = current->children[pos];
}

// Now we're at a leaf node
auto it = std::lower_bound(current->keys.begin(), current->keys.end(), key);
if (it != current->keys.end() && *it == key) {
    return true;
}
return false;
// END_CODE

